/* ================= REPORTS ================= */
S.rep={id:'daily',range:'7D'};
const RM={Today:.14,'7D':1,'30D':4.2,'12M':52};
const dSold=p=>p.sold30/30*7;
const REPORTS=[
['Sales','daily','Daily sales report','clock',()=>{const h=Array.from({length:14},(_,i)=>8+i);const v=h.map(x=>(Math.exp(-Math.pow(x-12.5,2)/6)*.6+Math.exp(-Math.pow(x-17.5,2)/4)+.15)*1650*bf());return{labels:h.map(x=>x+':00'),vals:v,cols:['Hour','Transactions','Revenue','Avg basket'],rows:h.map((x,i)=>[x+':00',Math.round(v[i]/37),money(v[i]),money(37+i%5)])}}],
['Sales','period','Weekly / monthly / yearly sales','calendar',r=>{const s=revSeries(r==='12M'?'12M':r==='30D'?'30D':'7D');return{labels:s.labels,vals:s.cur,line:s.prev,cols:['Period','Revenue','Previous','Change'],rows:s.labels.map((l,i)=>[l,money(s.cur[i]),money(s.prev[i]),((s.cur[i]/s.prev[i]-1)*100).toFixed(1)+'%'])}}],
['Sales','product','Product performance','package',r=>{const l=[...S.products].sort((a,b)=>b.sold30*b.price-a.sold30*a.price);return{labels:l.slice(0,10).map(p=>p.name.split(' ').slice(0,2).join(' ')),vals:l.slice(0,10).map(p=>dSold(p)*p.price*RM[r]),cols:['Product','Units','Revenue','Margin'],rows:l.map(p=>[p.name,num(dSold(p)*RM[r]),money(dSold(p)*p.price*RM[r]),((1-p.cost/(p.price/1.2))*100).toFixed(1)+'%'])}}],
['Sales','category','Category performance','layers',r=>{const c=Object.keys(CATS).map(k=>[k,sum(S.products.filter(p=>p.cat===k),p=>dSold(p)*p.price*RM[r])]).sort((a,b)=>b[1]-a[1]);const t=sum(c,x=>x[1]);return{labels:c.map(x=>x[0].split(' ')[0]),vals:c.map(x=>x[1]),cols:['Category','Revenue','Share'],rows:c.map(x=>[x[0],money(x[1]),(x[1]/t*100).toFixed(1)+'%'])}}],
['Sales','branch','Branch performance','store',r=>({labels:S.branches.map(b=>b.name),vals:S.branches.map(b=>b.rev/30*7*RM[r]),cols:['Branch','Revenue','Orders','Target attainment'],rows:S.branches.map(b=>[b.name,money(b.rev/30*7*RM[r]),num(b.orders/30*7*RM[r]),(b.rev/b.target*100).toFixed(1)+'%'])})],
['Sales','cashier','Cashier performance','userCheck',r=>{const l=S.employees.filter(e=>e.sales);return{labels:l.map(e=>e.name.split(' ')[0]),vals:l.map(e=>e.sales*RM[r]*1.4),cols:['Cashier','Sales','Transactions','Voids','Commission'],rows:l.map((e,i)=>[e.name,money(e.sales*RM[r]*1.4),num(e.txns*RM[r]*1.4),i%3,money(e.sales*e.comm/100*RM[r]*1.4)])}}],
['Finance','profit','Profit & margin','percent',r=>{const s=revSeries('12M');return{labels:s.labels,vals:s.cur.map(v=>v*.328),cols:['Month','Net sales','COGS','Gross profit','Margin'],rows:s.labels.map((l,i)=>{const n=s.cur[i]/1.2;return[l,money(n),money(n*.672),money(n*.328),'32.8%']})}}],
['Finance','tax','Tax report (VAT)','receipt',r=>{const s=revSeries('12M');return{labels:s.labels,vals:s.cur.map(v=>v-v/1.2),cols:['Month','Gross sales','Net sales','Output VAT (20%)'],rows:s.labels.map((l,i)=>[l,money(s.cur[i]),money(s.cur[i]/1.2),money(s.cur[i]-s.cur[i]/1.2)])}}],
['Finance','payment','Payment method report','card',r=>{const m=['Card','Cash','Digital wallet','Bank transfer','Gift card'],sh=[.58,.21,.14,.04,.03];const t=168000*RM[r]/7*bf();return{labels:m,vals:sh.map(x=>x*t),cols:['Method','Transactions','Amount','Share'],rows:m.map((x,i)=>[x,num(sh[i]*t/38),money(sh[i]*t),(sh[i]*100)+'%'])}}],
['Finance','discount','Discount report','tag',r=>({labels:S.promotions.map(p=>p.name.split(' ').slice(0,2).join(' ')),vals:S.promotions.map(p=>p.rev*.08),cols:['Promotion','Redemptions','Discount given','Revenue influenced'],rows:S.promotions.map(p=>[p.name,num(p.uses),money(p.rev*.08),money(p.rev)])})],
['Finance','refund','Refund report','undo',r=>{const l=S.orders.filter(o=>o.refunded);return{labels:l.slice(0,10).map(o=>o.inv.slice(-5)),vals:l.slice(0,10).map(o=>o.refunded),cols:['Invoice','Date','Customer','Refunded','Cashier'],rows:l.map(o=>[o.inv,fmtTime(o.time),o.customer,money(o.refunded),o.cashier])}}],
['Inventory','valuation','Inventory valuation','box',r=>{const c=Object.keys(CATS).map(k=>[k,sum(S.products.filter(p=>p.cat===k),p=>p.stock*p.cost),sum(S.products.filter(p=>p.cat===k),p=>p.stock*p.price)]);return{labels:c.map(x=>x[0].split(' ')[0]),vals:c.map(x=>x[1]),cols:['Category','Units','At cost','At retail'],rows:c.map(x=>[x[0],num(sum(S.products.filter(p=>p.cat===x[0]),p=>p.stock)),money(x[1]),money(x[2])])}}],
['Inventory','movement','Stock movement report','swap',r=>{const t={};S.movements.forEach(m=>t[m.type]=(t[m.type]||0)+Math.abs(m.qty));const k=Object.keys(t);return{labels:k,vals:k.map(x=>t[x]),fmt:num,cols:['Time','Product','Type','Qty','Reference'],rows:S.movements.map(m=>[fmtTime(m.time),P(m.pid).name,m.type,m.qty,m.reason])}}],
['Inventory','best','Best-selling products','flame',r=>{const l=[...S.products].sort((a,b)=>b.sold30-a.sold30).slice(0,10);return{labels:l.map(p=>p.name.split(' ')[0]),vals:l.map(p=>dSold(p)*RM[r]),fmt:num,cols:['Rank','Product','Units sold','Revenue'],rows:l.map((p,i)=>['#'+(i+1),p.name,num(dSold(p)*RM[r]),money(dSold(p)*RM[r]*p.price)])}}],
['Inventory','slow','Slow-moving products','trendDown',r=>{const l=[...S.products].sort((a,b)=>a.sold30/Math.max(1,a.stock)-b.sold30/Math.max(1,b.stock)).slice(0,8);return{labels:l.map(p=>p.name.split(' ')[0]),vals:l.map(p=>p.stock/(p.sold30/30||.1)),fmt:v=>Math.round(v)+'d',cols:['Product','Stock','Sold (30d)','Days of cover'],rows:l.map(p=>[p.name,p.stock,p.sold30,Math.round(p.stock/(p.sold30/30||.1))])}}],
['Inventory','dead','Dead-stock analysis','alert',r=>{const l=S.products.filter(p=>p.sold30<45);return{labels:l.map(p=>p.name.split(' ')[0]),vals:l.map(p=>p.stock*p.cost),cols:['Product','Stock','Value tied up','Last 30d sales','Action'],rows:l.map(p=>[p.name,p.stock,money(p.stock*p.cost),p.sold30,'Promote / delist'])}}],
['Partners','purchase','Purchase report','truck',r=>({labels:S.pos.map(p=>p.id),vals:S.pos.map(poVal),cols:['PO','Supplier','Value','Status'],rows:S.pos.map(p=>[p.id,S.suppliers.find(s=>s.id===p.sup).name,money(poVal(p)),p.status])})],
['Partners','supplier','Supplier report','users',r=>({labels:S.suppliers.map(s=>s.name.split(' ')[0]),vals:S.suppliers.map(s=>s.balance),cols:['Supplier','Orders','Balance','On-time','Rating'],rows:S.suppliers.map(s=>[s.name,s.orders,money(s.balance),s.ontime+'%',s.rating])})],
['Partners','customer','Customer report','user',r=>({labels:S.customers.map(c=>c.name.split(' ')[0]),vals:S.customers.map(c=>c.spent),cols:['Customer','Tier','Visits','Spend','Points'],rows:S.customers.map(c=>[c.name,c.tier,c.visits,money(c.spent),num(c.points)])})]];
PAGES.reports=()=>{const R0=REPORTS.find(r=>r[1]===S.rep.id);const d=R0[4](S.rep.range);const groups=[...new Set(REPORTS.map(r=>r[0]))];return `<div class="page">${head('Reporting studio','Reports & Analytics',`${REPORTS.length} ready-made reports — filter by period and branch, then export to CSV, Excel or PDF.`,`<div class="seg">${Object.keys(RM).map(k=>`<button class="${S.rep.range===k?'on':''}" onclick="S.rep.range='${k}';refresh()">${k}</button>`).join('')}</div>`)}<div class="grid g-nav" style="grid-template-columns:260px minmax(0,1fr)"><aside class="card pad rv" style="align-self:start;padding:14px">${groups.map(g=>`<div class="sec-t" style="margin:10px 10px 6px">${g}</div><div class="rep-list">${REPORTS.filter(r=>r[0]===g).map(r=>`<button class="rep-i ${S.rep.id===r[1]?'on':''}" onclick="S.rep.id='${r[1]}';refresh()">${ic(r[3],16)} ${r[2]}</button>`).join('')}</div>`).join('')}</aside><section class="card pad rv" style="--i:1"><div class="ch"><div><h3 style="font-size:20px">${R0[2]}</h3><p>${S.branch} · ${S.rep.range==='Today'?'Today':'Last '+S.rep.range} · generated ${new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</p></div><div class="row"><button class="btn sm" onclick="exportCSV('${R0[1]}-report',[${JSON.stringify(d.cols).replace(/"/g,"'")},...REPORTS.find(r=>r[1]==='${R0[1]}')[4](S.rep.range).rows])">${ic('download',14)} CSV / Excel</button><button class="btn sm" onclick="printReport()">${ic('printer',14)} PDF</button></div></div><div class="grid g3 mb">${[['Total',(d.fmt||money)(sum(d.vals))],['Average',(d.fmt||money)(sum(d.vals)/Math.max(1,d.vals.length))],['Peak',(d.fmt||money)(Math.max(0,...d.vals))]].map(x=>`<div style="background:var(--surface-2);border:1px solid var(--border);border-radius:14px;padding:14px 16px"><div class="xs muted">${x[0]}</div><b class="display" style="font-size:22px">${x[1]}</b></div>`).join('')}</div>${d.line?area({series:[{name:'Current',data:d.vals,c:'#5b4cf0'},{name:'Previous',data:d.line,c:'#b8b3e8',dash:true}],labels:d.labels,h:240}):bars(d.vals,d.labels,{fmt:d.fmt||moneyK,h:220,colors:['#5b4cf0','#7c6ff7','#8b7ffa','#a99fff']})}<div class="tw mt" id="rep-tab"><table><thead><tr>${d.cols.map((c,i)=>`<th class="${i?'tr':''}">${c}</th>`).join('')}</tr></thead><tbody>${d.rows.map((r,k)=>`<tr class="rv" style="--i:${Math.min(k,12)}">${r.map((c,i)=>`<td class="${i?'tr num':''}">${i?c:`<b>${esc(c)}</b>`}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section></div>${foot()}</div>`};
function printReport(){const R0=REPORTS.find(r=>r[1]===S.rep.id),d=R0[4](S.rep.range);printHTML(`<div style="font-family:Inter;padding:30px;color:#111"><h1 style="margin:0">${R0[2]}</h1><p>${S.settings.company} · ${S.branch} · ${S.rep.range} · ${new Date().toLocaleString('en-GB')}</p><table style="width:100%;border-collapse:collapse;font-size:12px"><tr>${d.cols.map(c=>`<th style="text-align:left;border-bottom:2px solid #111;padding:6px">${c}</th>`).join('')}</tr>${d.rows.map(r=>`<tr>${r.map(c=>`<td style="border-bottom:1px solid #ddd;padding:6px">${esc(c)}</td>`).join('')}</tr>`).join('')}</table></div>`)}

/* ================= BUSINESS INTELLIGENCE ================= */
PAGES.intelligence=()=>{const f=bf();const act=Array.from({length:12},(_,i)=>(34+i*1.1+Math.sin(i/1.5)*3)*1000*f);const fc=[...Array(11).fill(null),act[11],...Array.from({length:6},(_,i)=>(48+i*1.3+Math.sin((i+12)/1.5)*2.4)*1000*f)];const labels=[...Array.from({length:12},(_,i)=>'W'+(36+i)),...Array.from({length:6},(_,i)=>'W'+(48+i))];const kp=[['Revenue vs target',96.4,'var(--primary)'],['Gross margin vs 33%',99.4,'var(--teal)'],['Basket size vs £40',94.8,'var(--warning)'],['Conversion vs 30%',87.2,'var(--pink)']];return `<div class="page">${head('Insight lab','Business Intelligence','Forecasts, profitability, shopper behaviour and KPIs — all in real time.',`<button class="btn" onclick="exportCSV('bi-kpis',[['KPI','Attainment'],...${JSON.stringify(kp.map(k=>[k[0],k[1]])).replace(/"/g,"'")}])">${ic('download',16)} Export</button>`)}<section class="grid g4 mb">${kp.map((k,i)=>`<div class="card pad rv row" style="--i:${i};gap:16px">${ring(k[1],k[2])}<div><b class="sm">${k[0]}</b><div class="xs muted" style="margin-top:3px">${k[1]>=95?'On track':'Below target'} · this month</div></div></div>`).join('')}</section><div class="grid g-main mb"><section class="card pad rv" style="--i:4"><div class="ch"><div><h3>Sales forecast</h3><p>Weekly revenue · 6-week forecast with 92% confidence band</p></div><span class="badge pri">${ic('sparkles',12)} 94.2% accuracy</span></div><div class="legend" style="margin-bottom:10px"><span><i style="--c:#5b4cf0"></i>Actual</span><span><i class="dash" style="--c:#14b8a6"></i>Forecast</span></div>${area({series:[{name:'Actual',data:[...act,...Array(6).fill(null)],c:'#5b4cf0'},{name:'Forecast',data:fc,c:'#14b8a6',dash:true,band:true}],labels,h:270})}</section><section class="card pad rv" style="--i:5"><div class="ch"><div><h3>Product margin matrix</h3><p>Volume vs margin — bubble size = revenue</p></div></div>${scatter()}</section></div><div class="grid g3 mb"><section class="card pad rv" style="--i:6"><div class="ch"><div><h3>Shopper segments</h3><p>RFM clustering of 12,846 customers</p></div></div>${donut([{l:'Champions',v:1820,c:'#5b4cf0',fmt:'1,820'},{l:'Loyal',v:3410,c:'#14b8a6',fmt:'3,410'},{l:'Promising',v:2980,c:'#f29a0b',fmt:'2,980'},{l:'At risk',v:2240,c:'#e5479a',fmt:'2,240'},{l:'Hibernating',v:2396,c:'#b8b3e8',fmt:'2,396'}],'12.8K','customers')}</section><section class="card pad rv" style="--i:7"><div class="ch"><div><h3>Peak-hour analysis</h3><p>Use to plan staffing levels</p></div></div>${heatmap(9,f)}</section><section class="card pad rv" style="--i:8"><div class="ch"><div><h3>Year-over-year</h3><p>November 2026 vs 2025</p></div></div>${[['Revenue',154000*f,132400*f,1],['Transactions',4120*f,3810*f,0],['Avg basket',37.4,34.7,1],['Items per basket',5.8,5.3,2],['New customers',612*f,540*f,0]].map(r=>{const ch=(r[1]/r[2]-1)*100;const fm=r[3]===1?(r[0]==='Revenue'?moneyK:money):r[3]===2?v=>v.toFixed(1):num;return `<div class="li"><span style="flex:1" class="sm">${r[0]}</span><span class="xs muted num">${fm(r[2])}</span><b class="num sm" style="width:78px;text-align:right">${fm(r[1])}</b><span class="delta ${ch<0?'neg':''}" style="width:62px;justify-content:center">${ch>0?'+':''}${ch.toFixed(1)}%</span></div>`}).join('')}</section></div>${foot()}</div>`};
function scatter(){const W=420,H=280,L=40,B=30;const ps=S.products;const mxV=Math.max(1,...ps.map(p=>p.sold30));return `<div class="chart"><svg viewBox="0 0 ${W} ${H}" class="scatter" style="height:280px"><line class="gl" x1="${L}" x2="${W}" y1="${(H-B)/2}" y2="${(H-B)/2}"/><line class="gl" x1="${(W+L)/2}" x2="${(W+L)/2}" y1="0" y2="${H-B}"/><text class="ax" x="${W-4}" y="14" text-anchor="end">⭐ Stars</text><text class="ax" x="${L+4}" y="14">💎 Niche</text><text class="ax" x="${W-4}" y="${H-B-6}" text-anchor="end">🐮 Traffic drivers</text><text class="ax" x="${L+4}" y="${H-B-6}">⚠ Review</text><text class="ax" x="${(W+L)/2}" y="${H-6}" text-anchor="middle">Units sold →</text><text class="ax" x="12" y="${(H-B)/2}" transform="rotate(-90 12 ${(H-B)/2})" text-anchor="middle">Margin →</text>${ps.map((p,i)=>{const m=1-p.cost/(p.price/1.2);const x=L+p.sold30/mxV*(W-L-14),y=(H-B)-Math.max(0,Math.min(1,(m-.2)/.5))*(H-B-14);return `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${(4+Math.sqrt(p.sold30*p.price)/3).toFixed(1)}" fill="${CATS[p.cat].c}" fill-opacity=".55" stroke="${CATS[p.cat].c}" style="animation-delay:${i*40}ms;transform-origin:${x}px ${y}px"><title>${p.name} — ${p.sold30} units, ${(m*100).toFixed(0)}% margin</title></circle>`}).join('')}</svg></div>`}

/* ================= EXPIRY & LOSS ================= */
PAGES.expiry=()=>{const batches=S.products.filter(p=>p.expiry<=30&&p.stock>0).sort((a,b)=>a.expiry-b.expiry);const risk=sum(batches.filter(p=>p.expiry<=7),p=>p.stock*p.cost);return `<div class="page">${head('Risk & compliance','Expiry & Loss Prevention','Batch-level expiry tracking, waste management and suspicious-transaction monitoring.',`<button class="btn" onclick="lpSettings()">${ic('sliders',16)} Alert thresholds</button>`)}<section class="grid g4 mb">${kpi('Expiring within 7 days',cu(batches.filter(p=>p.expiry<=7).length),'','clock','var(--danger)',null,0,'batches')}${kpi('Value at risk',cu(risk,'money'),'','alert','var(--warning)',null,1,'at cost')}${kpi('Waste this week',cu(sum(S.waste,w=>w.qty*P(w.pid).cost),'money'),'-18%','trash','var(--teal)',[8,7,7,6,5,5,4,4],2)}${kpi('Flagged transactions',cu(S.suspicious.filter(s=>s.status==='Open').length),'','shield','var(--pink)',null,3,'awaiting review')}</section><div class="grid g-main mb"><section class="card pad rv" style="--i:4"><div class="ch"><div><h3>Near-expiry batches</h3><p>Act early: mark down or write off</p></div></div><div class="tw"><table><thead><tr><th>Product</th><th>Batch</th><th>Shelf life</th><th class="tr">Stock</th><th class="tr">Value</th><th></th></tr></thead><tbody>${batches.map((p,i)=>{const c=p.expiry<=2?'var(--danger)':p.expiry<=7?'var(--warning)':'var(--success)';const md=S.promotions.find(x=>x.type==='pct_prod'&&x.pid===p.id&&x.active);return `<tr class="rv" style="--i:${i}"><td><div class="pcell"><div class="pimg" style="background:${CATS[p.cat].tone};width:34px;height:34px;font-size:17px">${p.emoji}</div><b>${esc(p.name)}</b></div></td><td style="font-family:monospace">${p.batch}</td><td><div class="row" style="gap:8px"><div class="bar-mini" style="width:80px;--c:${c}"><i style="width:${Math.max(6,100-p.expiry/30*100)}%"></i></div><b style="color:${c}" class="sm">${p.expiry<=0?'Expired':p.expiry+' day'+(p.expiry>1?'s':'')}</b></div></td><td class="tr num">${p.stock}</td><td class="tr num">${money(p.stock*p.cost)}</td><td class="tr">${md?'<span class="badge pri">−30% live</span>':`<button class="btn xs soft" onclick="markDown(${p.id})">${ic('tag',12)} Mark down</button>`} <button class="btn xs danger" onclick="writeOff(${p.id})">${ic('trash',12)} Write off</button></td></tr>`}).join('')}</tbody></table></div></section><section class="card pad rv" style="--i:5"><div class="ch"><div><h3>Loss by cause</h3><p>Last 30 days</p></div></div>${donut([{l:'Expired',v:1240,c:'#e9445a'},{l:'Damaged',v:860,c:'#f29a0b'},{l:'Theft / unknown',v:540,c:'#5b4cf0'},{l:'Admin error',v:210,c:'#14b8a6'}],moneyK(2850),'total shrinkage')}</section></div><div class="grid g2"><section class="card pad rv" style="--i:6"><div class="ch"><div><h3>Suspicious transactions</h3><p>Excessive discounts, refunds and voids</p></div></div>${S.suspicious.map(s=>`<div class="alert" style="--c:${s.risk>70?'var(--danger)':'var(--warning)'};${s.status==='Resolved'?'opacity:.55':''}"><div class="fic" style="--c:${s.risk>70?'var(--danger)':'var(--warning)'}">${ic('flame',16)}</div><div style="flex:1;min-width:0"><b>${s.type}</b><small>${s.who} · ${s.ref} · ${s.amount?money(s.amount)+' · ':''}${ago(s.time)}</small><div class="progress" style="height:5px;margin-top:7px;max-width:200px"><i style="width:${s.risk}%;background:${s.risk>70?'var(--danger)':'var(--warning)'}"></i></div></div><div style="text-align:right"><div class="xs muted">Risk</div><b>${Math.round(s.risk)}</b></div>${s.status==='Open'?`<button class="btn xs" onclick="S.suspicious.find(x=>x.id===${s.id}).status='Resolved';audit('settings','Flag reviewed · ${s.type}');toast('Marked as reviewed');refresh()">Review</button>`:statusBadge('Resolved')}</div>`).join('')}</section><section class="card pad rv" style="--i:7"><div class="ch"><div><h3>Waste & adjustment log</h3><p>Every write-off with the responsible user</p></div></div><div class="tw"><table><thead><tr><th>Time</th><th>Product</th><th>Reason</th><th class="tr">Qty</th><th class="tr">Cost</th><th>User</th></tr></thead><tbody>${S.waste.map(w=>{const p=P(w.pid);return `<tr><td class="xs">${fmtTime(w.time)}</td><td><b>${p.emoji} ${esc(p.name)}</b></td><td><span class="badge ${w.reason==='Expired'?'bad':'warn'}">${w.reason}</span></td><td class="tr num">${w.qty}</td><td class="tr num">${money(w.qty*p.cost)}</td><td>${w.user}</td></tr>`}).join('')}</tbody></table></div></section></div>${foot()}</div>`};
function markDown(id){const p=P(id);S.promotions.unshift({id:Math.max(...S.promotions.map(x=>x.id))+1,name:'Clearance · '+p.name,type:'pct_prod',pid:id,pct:30,active:true,sched:'Until sold out',uses:0,rev:0});audit('price','Clearance mark-down 30% · '+p.name,p.batch);toast(`30% clearance applied to <b>${esc(p.name)}</b> at every till`);refresh()}
function writeOff(id){const p=P(id);confirmBox('Write off '+p.name+'?',`${p.stock} units (${money(p.stock*p.cost)} at cost) will be removed from stock and logged as waste.`,()=>{S.waste.unshift({time:new Date(),pid:id,qty:p.stock,reason:'Expired',user:'Alex Morgan'});S.movements.unshift({time:new Date(),pid:id,type:'Write-off',qty:-p.stock,reason:'Expired · '+p.batch,user:'Alex Morgan'});audit('stock','Write-off · '+p.name,p.stock+' units');p.stock=0;toast('Stock written off and logged');refresh()},{danger:true,label:'Write off'})}
function lpSettings(){modal({title:'Alert thresholds',sub:'Notify managers when risky activity happens',icon:'sliders',body:`<div class="fgrid"><label class="field">Excessive discount above (%)<input class="input" type="number" value="${S.settings.discountAlert}" id="lp-d"></label><label class="field">Refunds needing PIN above<input class="input" type="number" value="${S.settings.refundPinLimit}" id="lp-r"></label><label class="field">Near-expiry warning (days)<input class="input" type="number" value="7"></label><label class="field">Voids per hour before alert<input class="input" type="number" value="3"></label></div>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="S.settings.discountAlert=+$('#lp-d').value;S.settings.refundPinLimit=+$('#lp-r').value;audit('settings','Loss-prevention thresholds updated');closeModal();toast('Thresholds saved')">Save</button>`})}

/* ================= SECURITY ================= */
S.au={type:'All',q:''};
const AUIC={login:['logout','var(--info)'],price:['tag','var(--warning)'],refund:['undo','var(--danger)'],stock:['package','var(--teal)'],discount:['percent','var(--pink)'],user:['user','var(--primary)'],void:['x','var(--danger)'],settings:['sliders','var(--text-3)'],sale:['receipt','var(--success)'],approval:['key','var(--primary)']};
PAGES.security=()=>`<div class="page">${head('Trust & governance','Security & Audit','Authentication, role-based access, approvals and an immutable audit trail.',`<button class="btn" onclick="exportCSV('audit-trail',[['Time','User','Event','Reference','Type'],...S.audit.map(a=>[new Date(a.time).toLocaleString('en-GB'),a.who,a.what,a.ref,a.type])])">${ic('download',16)} Export audit log</button>`)}<section class="grid g4 mb">${kpi('Active sessions',cu(24),'','monitor','var(--primary)',null,0,'7 devices · 4 stores')}${kpi('Audit events (24h)',cu(1400+S.audit.length),'','activity','var(--teal)',[5,6,5,7,6,8,7,8],1)}${kpi('Pending approvals',cu(S.approvals.filter(a=>a.status==='Pending').length),'','key','var(--warning)',null,2,'refunds & discounts')}${kpi('Security alerts',cu(S.logins.filter(l=>!l.ok).length),'','shield','var(--danger)',null,3,'failed sign-in')}</section><div class="grid g-side mb"><section class="card pad rv" style="--i:4"><div class="row between wrap mb"><div><h3 class="display" style="margin:0;font-size:16px">Transaction audit trail</h3><p class="xs muted" style="margin:3px 0 0">Price edits, refunds, voids, stock and permission changes</p></div><div class="row"><select class="sel" style="width:auto;height:36px" onchange="S.au.type=this.value;$('#au').innerHTML=auditList()">${['All',...Object.keys(AUIC)].map(t=>`<option ${S.au.type===t?'selected':''}>${t}</option>`).join('')}</select></div></div><div id="au">${auditList()}</div></section><div class="grid" style="align-content:start"><section class="card pad rv" style="--i:5"><div class="ch"><div><h3>Approval queue</h3><p>Manager authorisation required</p></div></div>${S.approvals.map(a=>`<div class="alert" style="--c:var(--warning);flex-wrap:wrap"><div class="fic" style="--c:var(--warning)">${ic(a.type==='Refund'?'undo':'percent',16)}</div><div style="flex:1;min-width:150px"><b>${a.type} · ${money(a.amount)}</b><small>${a.ref} · ${a.by} · ${ago(a.time)}</small><div class="xs" style="margin-top:4px;color:var(--text-2)">“${a.note}”</div></div>${a.status==='Pending'?`<div class="row" style="gap:6px"><button class="btn xs danger" onclick="decide(${a.id},'Denied')">Deny</button><button class="btn xs ok" onclick="decide(${a.id},'Approved')">Approve</button></div>`:statusBadge(a.status)}</div>`).join('')}</section><section class="card pad rv" style="--i:6"><div class="ch"><div><h3>Security policy</h3></div></div>${[['twoFA','Two-factor authentication','Required for admins & managers'],['autoBackup','Encrypted nightly backups','AES-256 · 30-day retention']].map(([k,t,s])=>`<div class="li"><div style="flex:1"><b class="sm">${t}</b><div class="xs muted">${s}</div></div><label class="switch"><input type="checkbox" ${S.settings[k]?'checked':''} onchange="S.settings['${k}']=this.checked;audit('settings','${t} '+(this.checked?'enabled':'disabled'));toast('${t} '+(this.checked?'enabled':'disabled'))"><span></span></label></div>`).join('')}<div class="li"><div style="flex:1"><b class="sm">Auto-lock POS after</b><div class="xs muted">Idle session timeout</div></div><select class="sel" style="width:110px;height:34px" onchange="toast('Session timeout updated')"><option>5 min</option><option>15 min</option><option selected>30 min</option></select></div><div class="li"><div style="flex:1"><b class="sm">Price-change tracking</b><div class="xs muted">Always on · cannot be disabled</div></div><span class="badge ok">${ic('lock',11)} Locked</span></div></section></div></div><section class="card pad rv" style="--i:7"><div class="ch"><div><h3>Login activity</h3><p>Sign-ins across back office and POS terminals</p></div></div>${loginTable()}</section>${foot()}</div>`;
function auditList(){const l=S.audit.filter(a=>S.au.type==='All'||a.type===S.au.type).slice(0,30);return `<div class="feed" style="max-height:none">${l.map((a,i)=>{const x=AUIC[a.type]||['info','var(--primary)'];return `<div class="fi rv" style="--i:${Math.min(i,10)}"><div class="fic" style="--c:${x[1]}">${ic(x[0],15)}</div><div style="flex:1;min-width:0"><b>${esc(a.what)}</b><small>${a.who}${a.ref?' · '+esc(a.ref):''}</small></div><span class="ft">${fmtTime(a.time)}</span></div>`}).join('')||'<div class="empty">No events</div>'}</div>`}
function decide(id,st){const a=S.approvals.find(x=>x.id===id);a.status=st;audit('approval',`${a.type} ${st.toLowerCase()} · ${a.ref}`,money(a.amount));toast(`${a.type} ${st.toLowerCase()} — ${a.by} has been notified`,st==='Approved'?'ok':'info');refresh()}

/* ================= HARDWARE ================= */
PAGES.hardware=()=>`<div class="page">${head('Store devices','Hardware Integration','Scanners, printers, cash drawers, scales, payment terminals and customer displays.',`<button class="btn" onclick="testAll()">${ic('zap',16)} Run diagnostics</button><button class="btn pri" onclick="addDevice()">${ic('plus',16,2.4)} Add device</button>`)}<section class="grid g4 mb">${kpi('Devices online',cu(S.devices.filter(d=>d.status==='Connected').length),'','wifi','var(--success)',null,0,'of '+S.devices.length+' on REG-01')}${kpi('Registers configured',cu(12),'','monitor','var(--primary)',null,1,'4 stores')}${kpi('Receipts printed today',cu(1284),'','printer','var(--teal)',null,2,'0 paper alerts')}${kpi('Payment connectors',cu(4),'','card','var(--warning)',null,3,'Verifone · Stripe · Adyen · SumUp')}</section><section class="grid g3">${S.devices.map((d,i)=>`<div class="card dev hov rv" id="dev-${d.id}" style="--i:${i+4};--c:${d.status==='Connected'?'var(--success)':d.status==='Idle'?'var(--warning)':'var(--danger)'}"><div class="row between"><div class="dv-ic">${ic(d.ic,24)}</div><span class="row sm" style="gap:8px"><span class="status-dot"></span>${d.status}</span></div><div><b class="display" style="font-size:15px">${d.name}</b><div class="xs muted">${d.model} · ${d.conn}</div></div><div class="xs muted" id="dev-out-${d.id}" style="min-height:18px"></div><div class="row"><button class="btn sm" style="flex:1" onclick="testDevice(${d.id})">${ic('play',13)} Test</button><button class="btn sm ghost" onclick="toast('Configuration saved for ${d.name}')">${ic('sliders',14)}</button></div></div>`).join('')}</section>${foot()}</div>`;
function testDevice(id){const d=S.devices.find(x=>x.id===id),el=$('#dev-'+id),out=$('#dev-out-'+id);if(!el)return;el.classList.add('testing');out.innerHTML='<span class="spin" style="display:inline-block">⟳</span> Testing…';const res={1:'Read EAN-13 '+P(5).barcode+' in 42 ms',2:'Test receipt printed · 80 mm',3:'Drawer opened · kick pulse 120 ms',4:'Displaying “Welcome to Monarch”',5:'Terminal handshake OK · contactless ready',6:'Label calibrated · 58 × 40 mm',7:'Barcode label printed',8:'Reading 0.000 kg · zero calibrated',9:'Multi-touch OK · 10 points'}[id]||'Device self-test OK';setTimeout(()=>{el.classList.remove('testing');d.status='Connected';saveState();out.innerHTML=`<span class="up b">✓</span> ${res}`;toast(`${d.name}: ${res}`)},1600)}
function testAll(){S.devices.forEach((d,i)=>setTimeout(()=>testDevice(d.id),i*250))}
function addDevice(){modal({title:'Add device',sub:'Pair new hardware to a register',icon:'cpu',body:`<div class="fgrid"><label class="field">Device type<select class="sel" id="dv-t">${S.devices.map(d=>`<option value="${d.ic}">${d.name}</option>`).join('')}</select></label><label class="field">Register<select class="sel">${S.registers.map(r=>`<option>${r.id}</option>`).join('')}</select></label><label class="field">Model<input class="input" id="dv-m" placeholder="e.g. Epson TM-m30III"></label><label class="field">Connection<select class="sel" id="dv-c"><option>USB</option><option>Ethernet</option><option>Bluetooth</option><option>Wi-Fi</option></select></label></div>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="const s=$('#dv-t');S.devices.push({id:S.devices.length+1,name:s.options[s.selectedIndex].text,ic:s.value,model:$('#dv-m').value||'Generic',conn:$('#dv-c').value,status:'Idle'});saveState();closeModal();toast('Device paired');refresh()">Pair device</button>`})}

/* ================= OMNICHANNEL ================= */
const STAGES=[['New','var(--info)'],['Preparing','var(--warning)'],['Ready for pickup','var(--primary)'],['Completed','var(--success)']];
PAGES.omnichannel=()=>`<div class="page">${head('Commerce everywhere','Omnichannel','Unified inventory, customers and orders across stores, web, app and marketplaces.',`<button class="btn" onclick="syncAll()">${ic('refresh',16)} Sync now</button>`)}<section class="grid g4 mb">${kpi('Online orders (30d)',cu(342),'+22.4%','globe','var(--info)',[3,4,5,5,6,7,8,10],0)}${kpi('Click & Collect',cu(48),'+14%','store','var(--primary)',[4,4,5,5,6,6,7,8],1,'this week')}${kpi('Synced products',cu(4820),'','refresh','var(--teal)',null,2,'last sync 2 min ago')}${kpi('Fulfilment rate',cu(98.1,'pct'),'+0.6 pts','check','var(--success)',[7,7,8,8,8,9,9,9],3)}</section><section class="card pad rv mb" style="--i:4"><div class="ch"><div><h3>Online order board</h3><p>Move orders through preparation to collection</p></div></div><div class="kanban">${STAGES.map((s,si)=>{const l=S.online.filter(o=>o.stage===si);return `<div class="kcol"><div class="kcol-h" style="--c:${s[1]}"><i></i>${s[0]}<span class="badge" style="margin-left:auto">${l.length}</span></div>${l.map((o,i)=>`<div class="kcard" style="animation-delay:${i*60}ms"><div class="row between"><b class="sm">${o.id}</b><span class="badge ${o.ch==='Web'?'info':o.ch==='App'?'pri':'warn'}">${o.ch}</span></div><div class="sm" style="margin:6px 0 2px">${esc(o.cust)}</div><div class="xs muted">${o.items} items · ${o.type} · ${o.branch} · ${ago(o.time)}</div><div class="row between" style="margin-top:10px"><b class="num">${money(o.total)}</b>${si<3?`<button class="btn xs soft" onclick="advance('${o.id}')">${['Start picking','Mark ready','Collected'][si]} ${ic('arrowR',12)}</button>`:'<span class="up xs b">✓ Done</span>'}</div></div>`).join('')||'<div class="xs muted" style="text-align:center;padding:20px">No orders</div>'}</div>`}).join('')}</div></section><div class="grid g2"><section class="card pad rv" style="--i:5"><div class="ch"><div><h3>Sales by channel</h3><p>Online vs offline, last 30 days</p></div></div>${donut([{l:'In-store',v:612400,c:'#5b4cf0'},{l:'Web store',v:68200,c:'#0e9fe0'},{l:'Mobile app',v:31800,c:'#14b8a6'},{l:'Marketplace',v:12180,c:'#f29a0b'}],moneyK(724580),'all channels')}</section><section class="card pad rv" style="--i:6"><div class="ch"><div><h3>Channel connections</h3><p>Real-time inventory synchronisation</p></div></div>${[['Shopify web store','globe','Products, stock, orders, customers'],['Monarch mobile app','phone','Orders, loyalty, digital receipts'],['Amazon Marketplace','box','Stock & orders · 1,240 listings'],['Uber Eats / Deliveroo','truck','Rapid delivery · 2 stores']].map((c,i)=>`<div class="li"><div class="fic" style="--c:var(--primary)">${ic(c[1],16)}</div><div style="flex:1"><b class="sm">${c[0]}</b><div class="xs muted">${c[2]}</div></div><span class="badge ok dot sync-b">Synced ${i+1}m ago</span></div>`).join('')}</section></div>${foot()}</div>`;
function advance(id){const o=S.online.find(x=>x.id===id);o.stage++;if(o.stage===3){audit('sale','Online order fulfilled · '+id,money(o.total));toast(`${id} collected by ${esc(o.cust)}`)}else{saveState();toast(`${id} → ${STAGES[o.stage][0]}${o.stage===2?' · customer notified by SMS':''}`,'info')}refresh()}
function syncAll(){$$('.sync-b').forEach(b=>{b.className='badge warn sync-b';b.innerHTML='<span class="spin" style="display:inline-block">⟳</span> Syncing'});setTimeout(()=>{$$('.sync-b').forEach(b=>{b.className='badge ok dot sync-b';b.textContent='Synced just now'});toast('All channels synchronised · 4,820 products')},1800)}

/* ================= MOBILE ================= */
PAGES.mobile=()=>`<div class="page">${head('Manage from anywhere','Mobile Control','Monitor sales, stock and branches remotely with real-time push alerts.',`<button class="btn pri" onclick="testPush()">${ic('bell',16)} Send test notification</button>`)}<div class="grid g-nav" style="grid-template-columns:minmax(300px,380px) minmax(0,1fr);align-items:start"><div class="rv"><div class="phone"><div class="screen" id="phone-s"><div class="row between"><b class="display" style="font-size:18px">monarch<span style="color:var(--primary)">.</span></b>${avatar('Alex Morgan',30)}</div><div class="mcard" style="background:linear-gradient(135deg,#171b3a,#0e1124);color:#fff;border:0"><div style="font-size:10px;color:#aab0d3;letter-spacing:1px">TODAY · ALL STORES</div><div class="display" style="font-size:26px;font-weight:800">${money(24860+sum(sessionToday(),o=>o.total))}</div><div style="font-size:11px;color:#d5fd79">▲ 12.8% vs last week</div>${spark([4,6,5,7,6,8,9,8,10,11],'#d5fd79',240,40)}</div><div class="grid g2" style="gap:8px"><div class="mcard"><div class="xs muted">Orders</div><b>642</b></div><div class="mcard"><div class="xs muted">Low stock</div><b style="color:var(--warning)">${S.products.filter(p=>p.stock<p.min).length}</b></div></div>${S.branches.map(b=>`<div class="mcard row" style="padding:10px 12px;gap:10px"><span style="width:8px;height:8px;border-radius:50%;background:${b.c}"></span><span class="xs" style="flex:1">${b.name}</span><b class="xs">${moneyK(b.rev)}</b></div>`).join('')}</div></div></div><div class="grid" style="align-content:start"><section class="card pad rv" style="--i:1"><div class="ch"><div><h3>Push notification preferences</h3><p>Choose which events reach managers’ phones</p></div></div>${[['sales','Sales milestones','When a store hits its daily target'],['stock','Low-stock alerts','When a product drops below minimum'],['refund','Refund & void alerts','Every refund over £50 and all voids'],['large','Large transactions','Single sales above £500'],['daily','Daily summary','End-of-day report at 22:00'],['expiry','Expiry warnings','Batches expiring within 3 days']].map(([k,t,s])=>`<div class="li"><div style="flex:1"><b class="sm">${t}</b><div class="xs muted">${s}</div></div><label class="switch"><input type="checkbox" ${S.notifPrefs[k]?'checked':''} onchange="S.notifPrefs['${k}']=this.checked;saveState();toast('${t} '+(this.checked?'on':'off'),'info')"><span></span></label></div>`).join('')}</section><section class="card pad rv" style="--i:2"><div class="ch"><div><h3>Connected devices</h3><p>23 managers use the mobile app</p></div><button class="btn sm" onclick="pairPhone()">${ic('plus',14)} Pair device</button></div>${[['Alex Morgan','iPhone 16 Pro','Active now'],['Sarah Collins','Pixel 9','12m ago'],['Marcus Lee','iPad Air','1h ago'],['Chloe Evans','iPhone 15','3h ago']].map(d=>`<div class="li">${avatar(d[0],32)}<div style="flex:1"><b class="sm">${d[0]}</b><div class="xs muted">${d[1]}</div></div><span class="xs ${d[2]==='Active now'?'up b':'muted'}">${d[2]}</span></div>`).join('')}</section></div></div>${foot()}</div>`;
function testPush(){const s=$('#phone-s');if(!s)return;const n=document.createElement('div');n.className='push';n.innerHTML=`<div class="logo" style="width:30px;height:30px;border-radius:9px;transform:none">${ic('trend',15,2.4)}</div><div style="flex:1"><b>Manchester hit its daily target 🎉</b><div class="muted">£9,120 · 106% of goal · just now</div></div>`;s.appendChild(n);setTimeout(()=>{n.classList.add('out');setTimeout(()=>n.remove(),400)},3800);toast('Test notification delivered to 23 devices')}
function pairPhone(){modal({title:'Pair a mobile device',sub:'Scan with the Monarch Manager app',size:'sm',icon:'phone',body:`<div style="display:grid;grid-template-columns:repeat(21,1fr);gap:2px;width:220px;margin:0 auto;padding:12px;background:#fff;border-radius:14px">${Array.from({length:441},(_,i)=>{const x=i%21,y=Math.floor(i/21);const f=(x<7&&y<7)||(x>13&&y<7)||(x<7&&y>13);const on=f?((x%14<7&&y%14<7)&&(Math.max(Math.abs((x%14)-3),Math.abs((y%14)-3))!==2)):((x*7+y*13+x*y)%3===0);return `<i style="aspect-ratio:1;background:${on?'#111':'#fff'};animation:fadeIn .3s ${(i%21)*15}ms both"></i>`}).join('')}</div><p class="xs muted" style="text-align:center;margin-top:12px">Pairing code expires in 5:00</p>`})}

/* ================= ADMIN ================= */
S.adm='company';
PAGES.admin=()=>{const st=S.settings;const f=(k,l,t='text',x='')=>`<label class="field ${x}">${l}<input class="input" type="${t}" value="${esc(st[k])}" oninput="S.settings['${k}']=${t==='number'?'+this.value':'this.value'};saveState();${S.adm==='receipt'?"$('#rp').innerHTML=receiptHTML(DEMO_O())":''}"></label>`;const tg=(k,l,s)=>`<div class="li"><div style="flex:1"><b class="sm">${l}</b><div class="xs muted">${s}</div></div><label class="switch"><input type="checkbox" ${st[k]?'checked':''} onchange="S.settings['${k}']=this.checked;saveState();${S.adm==='receipt'?"$('#rp').innerHTML=receiptHTML(DEMO_O())":''}"><span></span></label></div>`;const tabs=[['company','Company','store'],['tax','Tax & currency','percent'],['receipt','Receipt designer','receipt'],['invoice','Invoice numbering','layers'],['stores','Stores & registers','monitor']];let body='';if(S.adm==='company')body=`<div class="fgrid">${f('company','Legal company name','text','full')}${f('address','Registered address','text','full')}${f('phone','Phone')}${f('email','Email')}${f('vat','VAT number')}<label class="field">Time zone<select class="sel"><option>Europe/London (GMT)</option><option>Asia/Karachi (PKT)</option><option>Asia/Dubai (GST)</option></select></label></div>`;if(S.adm==='tax')body=`<div class="fgrid"><label class="field">Currency<select class="sel" onchange="S.settings.currency=this.value;saveState();toast('Currency switched to '+this.value+' — all prices updated');refresh()">${Object.keys(CUR).map(c=>`<option ${st.currency===c?'selected':''}>${c}</option>`).join('')}</select></label>${f('taxRate','Standard tax / VAT rate (%)','number')}<div class="full">${tg('taxInclusive','Tax-inclusive pricing','Shelf prices include VAT (UK standard). Turn off to add tax at checkout.')}${tg('showVat','Show VAT number on receipts','Required for VAT invoices')}</div><div class="full"><div class="sec-t">Tax classes</div><div class="tw"><table><thead><tr><th>Class</th><th>Rate</th><th>Applies to</th></tr></thead><tbody><tr><td><b>Standard</b></td><td>${st.taxRate}%</td><td>Household, personal care, beverages, snacks</td></tr><tr><td><b>Reduced</b></td><td>5%</td><td>Energy-saving goods, children’s car seats</td></tr><tr><td><b>Zero</b></td><td>0%</td><td>Most food, books, children’s clothing</td></tr></tbody></table></div></div></div>`;if(S.adm==='receipt')body=`<div class="grid g2"><div>${f('receiptHeader','Header message','text')}<div style="height:12px"></div>${f('receiptFooter','Footer / returns policy','text')}<div class="mt">${tg('showLogo','Print logo','Brand mark at the top')}${tg('showBarcode','Print invoice barcode','Scan to look up for returns')}${tg('showVat','Show VAT number','Legal requirement for VAT receipts')}</div><div class="sec-t">Digital receipts</div><div class="row wrap"><span class="chip on">${ic('mail',13)} Email</span><span class="chip on">${ic('msg',13)} SMS</span><span class="chip">${ic('phone',13)} WhatsApp</span></div></div><div class="rec-prev" id="rp">${receiptHTML(DEMO_O())}</div></div>`;if(S.adm==='invoice')body=`<div class="fgrid">${f('invPrefix','Invoice prefix')}${f('nextInv','Next invoice number','number')}<div class="full alert" style="--c:var(--primary)"><div class="fic" style="--c:var(--primary)">${ic('info',16)}</div><div><b>Next invoice: ${esc(st.invPrefix)}${st.nextInv}</b><small>Sequential, gap-free numbering per company — required for tax compliance.</small></div></div></div>`;if(S.adm==='stores')body=`<div class="tw"><table><thead><tr><th>Store</th><th>Manager</th><th>Registers</th><th>Hours</th><th>Status</th></tr></thead><tbody>${S.branches.map(b=>`<tr><td><b>${b.name}</b><div class="xs muted">${b.id}</div></td><td>${b.manager}</td><td>${S.registers.filter(r=>r.branch===b.id).length||2}</td><td>07:00 – 22:00</td><td>${statusBadge('Active')}</td></tr>`).join('')}</tbody></table></div><button class="btn sm mt" onclick="toast('Store wizard opened','info')">${ic('plus',14)} Add store</button>`;return `<div class="page">${head('Control centre','Admin & Settings','Company profile, tax, receipts, numbering and business structure.',`<button class="btn pri" onclick="audit('settings','System settings saved · '+S.adm);toast('Settings saved and synced to all registers')">${ic('check',16,2.4)} Save changes</button>`)}<div class="grid g-nav" style="grid-template-columns:240px minmax(0,1fr)"><aside class="card rv" style="padding:12px;align-self:start"><div class="rep-list">${tabs.map(t=>`<button class="rep-i ${S.adm===t[0]?'on':''}" onclick="S.adm='${t[0]}';refresh()">${ic(t[2],16)} ${t[1]}</button>`).join('')}</div><div class="divider"></div><div class="rep-list">${[['employees','Users & access','users'],['promotions','Price policies','tag'],['hardware','Integrations','cpu'],['database','Data management','db']].map(t=>`<button class="rep-i" onclick="go('${t[0]}')">${ic(t[2],16)} ${t[1]}</button>`).join('')}</div></aside><section class="card pad rv" style="--i:1"><div class="ch"><div><h3>${tabs.find(t=>t[0]===S.adm)[1]}</h3><p>Changes apply to every store and register</p></div></div>${body}</section></div>${foot()}</div>`};
const DEMO_O=()=>({inv:S.settings.invPrefix+S.settings.nextInv,time:new Date(),cashier:'Daniel Reed',reg:'REG-01',cid:1,customer:'Olivia James',items:[{name:'Single-Origin Coffee 1kg',qty:1,price:18.5,disc:0},{name:'Butter Croissants (4)',qty:2,price:2.95,disc:0}],sub:24.4,itemDisc:0,lines:[],invDisc:0,tax:4.07,total:24.4,pays:[{method:'Card',amount:24.4,ref:'•••• 4821'}],change:0,earned:24});

/* ================= DATABASE ================= */
PAGES.database=()=>`<div class="page">${head('Reliable infrastructure','Database & System','Centralised data, real-time sync, automated backups and API-first connectivity (`Vercel + MongoDB` ready).',`<button class="btn danger" onclick="confirmBox('Reset demo data?','This will restore all products, orders, customers and settings back to factory defaults.',()=>resetDemoState(),{danger:true,label:'Reset data'})">${ic('undo',16)} Reset demo data</button><button class="btn" onclick="exportJSON()">${ic('download',16)} Full data export</button><button class="btn pri" onclick="runBackup()">${ic('cloud',16)} Back up now</button>`)}<section class="grid g4 mb">${kpi('System uptime',cu(99.98,'pct'),'','activity','var(--success)',[9,9,9,9,9,9,9,9],0,'last 90 days')}${kpi('API latency (p95)',cu(84)+' ms','-12%','zap','var(--primary)',[8,7,7,6,6,5,5,4],1)}${kpi('Records stored',cu(2840000),'','db','var(--teal)',null,2,'18 collections')}${kpi('Last backup',`<span style="font-size:22px">${ago(S.backups[0].time)}</span>`,'','cloud','var(--warning)',null,3,S.backups[0].size)}</section><div class="grid g-main mb"><section class="card pad rv" style="--i:4"><div class="ch"><div><h3>Backups & recovery</h3><p>Encrypted, geo-redundant · 30-day retention</p></div></div><div id="bk-prog"></div><div class="tw"><table><thead><tr><th>Backup</th><th>Time</th><th>Type</th><th>Size</th><th>Duration</th><th>Status</th><th></th></tr></thead><tbody>${S.backups.map((b,i)=>`<tr class="rv" style="--i:${i}"><td><b>${b.id}</b></td><td>${fmtTime(b.time)}</td><td>${b.type}</td><td class="num">${b.size}</td><td>${b.dur}</td><td>${statusBadge(b.status)}</td><td class="tr"><button class="btn xs" onclick="confirmBox('Restore ${b.id}?','The system will restore data to ${fmtTime(b.time)}. A safety backup is taken first.',()=>toast('Restore simulated — production requires owner approval','info'),{danger:true,label:'Restore'})">${ic('undo',13)} Restore</button></td></tr>`).join('')}</tbody></table></div></section><section class="card pad rv" style="--i:5"><div class="ch"><div><h3>Synchronisation & Cloud</h3><p>Store ↔ cloud replication (${S.cloudStatus})</p></div></div>${S.branches.map((b,i)=>`<div class="li"><div class="fic" style="--c:${b.c}">${ic('refresh',15)}</div><div style="flex:1"><b class="sm">${b.name}</b><div class="xs muted">${ri(12,90)} events/min · lag ${ri(40,180)} ms</div></div><span class="badge ok dot live">Live</span></div>`).join('')}<div class="li"><div class="fic" style="--c:var(--info)">${ic('globe',15)}</div><div style="flex:1"><b class="sm">Omnichannel connectors</b><div class="xs muted">4 channels</div></div><span class="badge ok dot live">Live</span></div><div class="sec-t">Offline + Cloud Persistence</div><p class="sm muted" style="margin:0">Every transaction, stock change, PO, customer, and setting persists automatically in localStorage and syncs with <code>/api/state</code> when MongoDB is connected on Vercel.</p></section></div><div class="grid g2"><section class="card pad rv" style="--i:6"><div class="ch"><div><h3>Import / export</h3><p>Excel, CSV and PDF</p></div></div><div class="grid g2" style="gap:10px">${[['Import products (CSV)','upload',"importCSVPrompt()"],['Export catalog (CSV)','download',"go('inventory')"],['Export sales (Excel)','download',"exportOrders()"],['Export customers','download',"go('customers')"],['Export reports (PDF)','printer',"go('reports')"],['Full backup (JSON)','db',"exportJSON()"]].map(x=>`<button class="btn" style="justify-content:flex-start;height:48px" onclick="${x[2]}">${ic(x[1],16)} ${x[0]}</button>`).join('')}</div></section><section class="card pad rv" style="--i:7"><div class="ch"><div><h3>REST API</h3><p>24 endpoints · OAuth 2.0 · webhooks</p></div><button class="btn sm" onclick="toast('API key copied to clipboard')">${ic('key',14)} API keys</button></div>${[['GET','/api/state','Get live state (MongoDB/Vercel)'],['POST','/api/state','Persist full state to MongoDB'],['GET','/v1/products','List catalog'],['POST','/v1/sales','Create a sale'],['GET','/v1/inventory/{sku}','Stock by branch'],['PATCH','/v1/promotions/{id}','Update promotion']].map(a=>`<div class="li" style="font-family:monospace;font-size:12.5px"><span class="badge ${a[0]==='GET'?'ok':a[0]==='POST'?'pri':'warn'}" style="width:56px;justify-content:center">${a[0]}</span><span style="flex:1">${a[1]}</span><span class="xs muted" style="font-family:Inter">${a[2]}</span></div>`).join('')}</section></div>${foot()}</div>`;
function runBackup(){const el=$('#bk-prog');if(!el)return;el.innerHTML=`<div class="alert" style="--c:var(--primary);margin-bottom:16px"><div class="fic" style="--c:var(--primary)">${ic('cloud',16)}</div><div style="flex:1"><b id="bk-t">Creating snapshot…</b><div class="progress stripe" style="margin-top:8px"><i id="bk-b" style="width:0"></i></div></div><b id="bk-p">0%</b></div>`;let p=0;const steps=['Creating snapshot…','Compressing 18 collections…','Encrypting (AES-256)…','Uploading to EU-West & EU-North…','Verifying integrity…'];const t=setInterval(()=>{p+=Math.random()*9+4;if(p>=100){p=100;clearInterval(t);S.backups.unshift({id:'BK-'+(5521+S.backups.length-6),time:new Date(),type:'Manual',size:'1.85 GB',status:'Success',dur:'14s'});audit('settings','Manual backup completed','1.85 GB');setTimeout(()=>{toast('Backup completed and verified');refresh()},400)}const b=$('#bk-b');if(!b)return clearInterval(t);b.style.width=p+'%';$('#bk-p').textContent=Math.round(p)+'%';$('#bk-t').textContent=steps[Math.min(4,Math.floor(p/20))]},260)}
function exportJSON(){const data={exported:new Date(),settings:S.settings,products:S.products,customers:S.customers,orders:S.orders,suppliers:S.suppliers,purchaseOrders:S.pos,promotions:S.promotions,employees:S.employees};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='monarch-backup-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();toast('Full data export downloaded')}

/* ================= AI ================= */
function reorders(){return S.products.map(p=>{const v=p.sold30/30;const sup=S.suppliers.find(s=>s.cat===p.cat)||S.suppliers[4];const cover=v?p.stock/v:999;const sug=Math.max(0,Math.ceil(v*(sup.lead+14)-p.stock));return{p,v,cover,sug,sup}}).filter(x=>x.sug>0&&x.cover<14).sort((a,b)=>a.cover-b.cover)}
PAGES.ai=()=>{const ro=reorders();return `<div class="page">${head('Next generation','AI & Automation','Predictive insights, smart replenishment, fraud detection and personalised campaigns.',`<button class="btn pri" onclick="go('intelligence')">${ic('trend',16)} Open forecasts</button>`)}<section class="hero rv mb" style="grid-template-columns:1fr"><div class="orb"></div><div><small>✦ MONARCH AI · DAILY BRIEFING</small><h2 style="font-size:clamp(20px,2.2vw,28px);letter-spacing:-.6px;line-height:1.35;max-width:900px" id="ai-brief" class="typing"></h2><div class="row wrap" style="margin-top:16px;gap:8px"><button class="btn sm" style="background:#ffffff14;color:#fff;border-color:#ffffff20" onclick="createAllPO()">${ic('truck',14)} Create ${ro.length} reorders</button><button class="btn sm" style="background:#d5fd79;color:#0e1121;border-color:#d5fd79" onclick="launchCampaign(0)">${ic('zap',14)} Launch suggested campaign</button></div></div></section><section class="grid g4 mb">${[['Demand spike expected','Sparkling drinks +34% this weekend (forecast 18°C, sunny).','trend','var(--success)'],['Margin opportunity','Raise Sea Salt Crisps to £1.75 — elasticity suggests −2% volume, +9% profit.','percent','var(--primary)'],['Churn risk','312 Gold members haven’t visited in 30 days. Win-back offer recommended.','users','var(--pink)'],['Anomaly detected','REG-04 void rate is 4.2× the network average this week.','shield','var(--danger)']].map((x,i)=>`<div class="insight hov card rv" style="--i:${i+1};--c:${x[3]}"><div class="fic" style="--c:${x[3]};margin-bottom:12px">${ic(x[2],16)}</div><b class="display" style="font-size:14.5px">${x[0]}</b><p class="sm muted" style="margin:6px 0 0">${x[1]}</p></div>`).join('')}</section><div class="grid g-main mb"><section class="card pad rv" style="--i:5"><div class="ch"><div><h3>Smart replenishment</h3><p>Reorder quantities from sales velocity, lead time and 14-day safety cover</p></div><button class="btn sm pri" onclick="createAllPO()">${ic('check',14,2.4)} Approve all</button></div><div class="tw"><table><thead><tr><th>Product</th><th class="tr">Stock</th><th class="tr">Daily velocity</th><th>Days of cover</th><th>Supplier</th><th class="tr">Suggested</th><th></th></tr></thead><tbody>${ro.map((x,i)=>`<tr class="rv" style="--i:${i}"><td><div class="pcell"><div class="pimg" style="width:34px;height:34px;font-size:17px;background:${CATS[x.p.cat].tone}">${x.p.emoji}</div><b>${esc(x.p.name)}</b></div></td><td class="tr num">${x.p.stock}</td><td class="tr num">${x.v.toFixed(1)}/day</td><td><span class="badge ${x.cover<3?'bad':x.cover<7?'warn':'info'}">${x.cover<1?'< 1':x.cover.toFixed(1)} days</span></td><td class="sm">${x.sup.name}</td><td class="tr num"><b>${x.sug}</b></td><td class="tr"><button class="btn xs soft" onclick="newPO([{pid:${x.p.id},qty:${x.sug}}])">${ic('plus',12)} PO</button></td></tr>`).join('')}</tbody></table></div></section><section class="card pad rv" style="--i:6"><div class="ch"><div><h3>Personalised campaigns</h3><p>Generated from purchase affinities</p></div></div>${CAMPS.map((c,i)=>`<div class="alert" style="--c:var(--primary)"><div class="fic" style="--c:${c.c}">${ic(c.ic,16)}</div><div style="flex:1"><b>${c.t}</b><small>${c.s}</small></div><button class="btn xs ${c.done?'':'pri'}" ${c.done?'disabled':''} onclick="launchCampaign(${i})">${c.done?'Live':'Launch'}</button></div>`).join('')}</section></div><section class="card pad rv" style="--i:7"><div class="ch"><div><h3>Fraud risk detection</h3><p>Anomaly scores across cashiers this week</p></div></div>${bars([12,18,9,64,22,14],['Daniel','Priya','Hannah','Ryan','Sarah','Chloe'],{fmt:v=>v+'/100',colors:['#14b8a6','#14b8a6','#14b8a6','#e9445a','#f29a0b','#14b8a6'],h:180})}</section>${foot()}</div>`};
const CAMPS=[{t:'Coffee lovers: 15% off beans',s:'486 customers buy coffee weekly · est. +£1,240',ic:'coffee',c:'var(--warning)',pid:8,pct:15},{t:'Win back lapsed Gold members',s:'312 customers · double points for 14 days',ic:'users',c:'var(--pink)'},{t:'Breakfast cross-sell',s:'Croissant buyers → OJ attach rate 18% → 31%',ic:'sparkles',c:'var(--teal)'}];
function launchCampaign(i){const c=CAMPS[i];if(c.done)return;c.done=true;if(c.pid)S.promotions.unshift({id:Math.max(...S.promotions.map(x=>x.id))+1,name:'AI · '+c.t,type:'pct_prod',pid:c.pid,pct:c.pct,active:true,sched:'Next 14 days',uses:0,rev:0});audit('price','AI campaign launched · '+c.t);toast(`Campaign <b>${c.t}</b> launched`);refresh()}
function createAllPO(){const ro=reorders();if(!ro.length)return toast('Stock levels are healthy — nothing to reorder','info');const by={};ro.forEach(x=>(by[x.sup.id]=by[x.sup.id]||[]).push({pid:x.p.id,qty:x.sug,cost:x.p.cost,rec:0}));Object.entries(by).forEach(([sid,lines])=>{S.pos.unshift({id:'PO-'+(2043+S.pos.length-5),sup:+sid,status:'Draft',created:new Date(),eta:new Date(Date.now()+3*DAY),lines})});audit('stock','AI reorder drafts created',Object.keys(by).length+' POs');toast(`${Object.keys(by).length} draft purchase orders created — review in Purchasing`);S.pur='orders';go('purchasing')}
function typeBrief(){const el=$('#ai-brief');if(!el)return;const txt=`Good afternoon, Alex. Revenue is tracking 12.8% ahead of last Sunday. ${reorders().length} products will run out within two weeks, ${S.products.filter(p=>p.expiry<=3&&p.stock>0).length} fresh batches need marking down today, and a coffee campaign could add ~£1,240 this month.`;let i=0;const t=setInterval(()=>{if(!document.body.contains(el))return clearInterval(t);el.textContent=txt.slice(0,++i);if(i>=txt.length){clearInterval(t);setTimeout(()=>el.classList.remove('typing'),1500)}},16)}

/* ================= COMMAND PALETTE & NOTIFICATIONS ================= */
let CMDI=0;
function openCmd(){$('#pop-root').innerHTML=`<div class="cmd-ov" onmousedown="if(event.target===this)closeCmd()"><div class="cmd"><div class="cmd-in">${ic('search',20)}<input id="cmd-q" placeholder="Search pages, products, customers or actions…" oninput="CMDI=0;cmdDraw()" onkeydown="cmdKey(event)"><kbd>ESC</kbd></div><div class="cmd-l" id="cmd-l"></div><div class="cmd-f"><span><kbd>↑</kbd> <kbd>↓</kbd> navigate</span><span><kbd>↵</kbd> open</span><span><kbd>esc</kbd> close</span></div></div></div>`;CMDI=0;cmdDraw();setTimeout(()=>$('#cmd-q').focus(),30)}
function closeCmd(){$('#pop-root').innerHTML=''}
function cmdItems(){const q=($('#cmd-q')?.value||'').toLowerCase();const acts=[['New sale','scan',()=>go('pos')],['Add product','plus',()=>addProduct()],['New purchase order','truck',()=>newPO()],['Add customer','userPlus',()=>addCustomer()],['Issue gift card','gift',()=>issueGift()],['New promotion','zap',()=>newPromo()],['Run backup','cloud',()=>{go('database');setTimeout(runBackup,400)}],['Toggle dark mode','moon',()=>toggleTheme()]];const g=[['Actions',acts.filter(a=>a[0].toLowerCase().includes(q)).map(a=>({t:a[0],ic:a[1],s:'Action',f:a[2]}))],['Pages',Object.entries(NAMES).filter(([k,n])=>n.toLowerCase().includes(q)).map(([k,n])=>({t:n,ic:NAVIC[k],s:'Page',f:()=>go(k)}))]];if(q){g.push(['Products',S.products.filter(p=>(p.name+p.sku+p.barcode).toLowerCase().includes(q)).slice(0,5).map(p=>({t:p.emoji+' '+p.name,ic:'package',s:money(p.price)+' · '+p.stock+' in stock',f:()=>{go('inventory');setTimeout(()=>productDrawer(p.id),300)}}))]);g.push(['Customers',S.customers.filter(c=>c.name.toLowerCase().includes(q)).slice(0,4).map(c=>({t:c.name,ic:'user',s:c.tier,f:()=>{go('customers');setTimeout(()=>custDrawer(c.id),300)}}))]);g.push(['Orders',S.orders.filter(o=>o.inv.toLowerCase().includes(q)).slice(0,4).map(o=>({t:o.inv+' · '+o.customer,ic:'receipt',s:money(o.total),f:()=>{go('orders');setTimeout(()=>orderDrawer(o.id),300)}}))])}return g.filter(x=>x[1].length)}
function cmdDraw(){const g=cmdItems();let k=0;window._cmdF=[];$('#cmd-l').innerHTML=g.map(([n,items])=>`<div class="cmd-g">${n}</div>${items.map(it=>{const i=k++;window._cmdF.push(it.f);return `<button class="cmd-r ${i===CMDI?'on':''}" onmouseenter="CMDI=${i};$$('.cmd-r').forEach((b,j)=>b.classList.toggle('on',j===${i}))" onclick="closeCmd();window._cmdF[${i}]()"><span class="ri">${ic(it.ic,15)}</span>${esc(it.t)}<small>${it.s}</small></button>`}).join('')}`).join('')||`<div class="empty">${ic('search',22)}<div>No results</div></div>`}
function cmdKey(e){const n=(window._cmdF||[]).length;if(e.key==='ArrowDown'){e.preventDefault();CMDI=(CMDI+1)%n;cmdDraw();$('.cmd-r.on')?.scrollIntoView({block:'nearest'})}if(e.key==='ArrowUp'){e.preventDefault();CMDI=(CMDI-1+n)%n;cmdDraw();$('.cmd-r.on')?.scrollIntoView({block:'nearest'})}if(e.key==='Enter'&&n){closeCmd();window._cmdF[CMDI]()}}
function openNotifs(e){e.stopPropagation();if($('#pop-root .pop')){$('#pop-root').innerHTML='';return}const r=$('#bell').getBoundingClientRect();$('#pop-root').innerHTML=`<div class="pop" style="top:${r.bottom+10}px;right:${Math.max(12,innerWidth-r.right-20)}px"><div class="pop-h"><b>Notifications</b><button class="btn xs ghost" onclick="S.notifs.forEach(n=>n.unread=false);updateBell();saveState();$('#pop-root').innerHTML=''">Mark all read</button></div><div class="pop-l">${S.notifs.map((n,i)=>`<div class="fi ${n.unread?'unread':''}" onclick="S.notifs[${i}].unread=false;updateBell();saveState();$('#pop-root').innerHTML='';go('${n.go}')"><div class="fic" style="--c:${n.c}">${ic(n.ic,16)}</div><div style="min-width:0"><b>${n.t}</b><small>${n.s}</small></div><span class="ft">${ago(n.time)}</span></div>`).join('')}</div></div>`}
document.addEventListener('click',e=>{if(!e.target.closest('.pop')&&!e.target.closest('#bell')&&!e.target.closest('#me-btn')&&$('#pop-root .pop'))$('#pop-root').innerHTML=''});
document.addEventListener('keydown',e=>{
  if($('#auth-root .auth-ov')){
    if(AUTH.mode==='pin'){
      if(/^[0-9]$/.test(e.key)){e.preventDefault();authKey(e.key)}
      else if(e.key==='Backspace'){e.preventDefault();authKey('back')}
      else if(e.key==='Escape'){e.preventDefault();authKey('clear')}
    }
    return;
  }
  if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#pop-root .cmd-ov')?closeCmd():openCmd()}
  if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='l'){e.preventDefault();lockPOS()}
  if(e.key==='Escape'){if($('#pop-root').innerHTML)closeCmd();else if($('#modal-root .ov'))closeModal();else if($('#drawer-root .drawer'))closeDrawer()}
});

/* ================= ENTERPRISE AUTHENTICATION & POS PIN LOCK ================= */
const AUTH={mode:'pin',pin:'',uid:1};
function updateUserChip(){
  const u=S.user||S.employees[0];
  const av=$('#me-av'),nm=$('#me-name'),rl=$('#me-role');
  if(av){av.textContent=initials(u.name);av.style.background=avc(u.name)}
  if(nm)nm.textContent=u.name;
  if(rl)rl.textContent=`${u.role} · ${u.branch}`;
}
function openAuthScreen(locked=false){
  AUTH.pin='';
  const root=$('#auth-root');
  if(!root)return;
  const sel=S.employees.find(e=>e.id===AUTH.uid)||S.employees[0];
  root.innerHTML=`<div class="auth-ov" id="auth-ov">
    <div class="auth-shell">
      <div class="auth-side">
        <div>
          <div class="row" style="gap:12px;margin-bottom:20px">
            <div class="logo" style="width:42px;height:42px;transform:rotate(-6deg)"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M4 19V6l8 8 8-8v13"/></svg></div>
            <div><b style="font:800 22px 'Plus Jakarta Sans',sans-serif;letter-spacing:-.6px">monarch<span style="color:#d5fd79">.</span></b><div style="font-size:10px;letter-spacing:2.6px;color:#8c92b5;font-weight:700">ENTERPRISE RETAIL OS</div></div>
          </div>
          <h2 class="display" style="margin:0 0 6px;font-size:24px;letter-spacing:-.6px">${locked?'Terminal Locked':'Sign in to Workspace'}</h2>
          <p style="margin:0;color:#9ba1c4;font-size:13px">Select an account for quick 1-tap demo sign-in or enter your 4-digit POS PIN / credentials.</p>
          <div class="auth-users">
            ${S.employees.slice(0,5).map(e=>`<button class="auth-u ${e.id===sel.id?'on':''}" onclick="authPickUser(${e.id})">
              ${avatar(e.name,36)}
              <div><b>${esc(e.name)}</b><small>${e.role} · ${e.branch==='All'?'All Branches':e.branch}</small></div>
              <span class="pin-pill">PIN ${e.pin}</span>
            </button>`).join('')}
          </div>
        </div>
        <div class="row between xs" style="color:#7d84ab;border-top:1px solid #ffffff12;padding-top:14px">
          <span>${ic('shield',13)} RBAC & Audit Trail Active</span>
          <span>REG-01 · v4.2</span>
        </div>
      </div>
      <div class="auth-form">
        <div class="seg" style="background:#ffffff0c;border-color:#ffffff16;margin:0 auto 22px">
          <button class="${AUTH.mode==='pin'?'on':''}" style="${AUTH.mode==='pin'?'background:#5b4cf0;color:#fff':''}" onclick="AUTH.mode='pin';openAuthScreen(${locked})">${ic('key',14)} POS PIN Pad</button>
          <button class="${AUTH.mode==='email'?'on':''}" style="${AUTH.mode==='email'?'background:#5b4cf0;color:#fff':''}" onclick="AUTH.mode='email';openAuthScreen(${locked})">${ic('mail',14)} Email & Password</button>
        </div>
        ${AUTH.mode==='pin'?`
          <div style="text-align:center">
            <div style="display:inline-flex;align-items:center;gap:10px;padding:6px 14px 6px 6px;border-radius:30px;background:#ffffff0d;border:1px solid #ffffff14">
              ${avatar(sel.name,28)}
              <span class="sm"><b>${esc(sel.name)}</b> · <span style="color:#a5abd0">${sel.role}</span></span>
            </div>
            <div class="pin-dots" id="pin-dots">
              ${[0,1,2,3].map(i=>`<span class="pin-dot ${AUTH.pin.length>i?'on':''}"></span>`).join('')}
            </div>
            <div class="keypad">
              ${[1,2,3,4,5,6,7,8,9,'C',0,'⌫'].map(k=>`<button class="kbtn" onclick="authKey('${k==='C'?'clear':k==='⌫'?'back':k}')">${k}</button>`).join('')}
            </div>
            <button class="btn pri" style="width:100%;max-width:290px;margin:16px auto 0;height:46px" onclick="completeSignIn(S.employees.find(e=>e.id===${sel.id}),'POS PIN Pad')">
              ${ic('zap',16)} Instant Sign In as ${esc(sel.name.split(' ')[0])} (PIN ${sel.pin})
            </button>
          </div>
        `:`
          <form onsubmit="event.preventDefault();submitEmailAuth()" style="display:grid;gap:14px;max-width:340px;margin:0 auto;width:100%">
            <label class="field" style="color:#b7bce0">Work email
              <input class="auth-input" id="au-email" type="email" value="${esc(sel.email)}" required>
            </label>
            <label class="field" style="color:#b7bce0">Password
              <input class="auth-input" id="au-pass" type="password" value="${esc(sel.password||'admin123')}" required>
            </label>
            <div class="row between xs" style="color:#9ba1c4">
              <label class="row" style="gap:7px;cursor:pointer"><input type="checkbox" checked> Remember register session</label>
              <span>Default: <b style="color:#d5fd79">admin123</b></span>
            </div>
            <button class="btn pri" type="submit" style="height:46px;margin-top:6px">${ic('lock',16)} Sign in to Monarch</button>
          </form>
        `}
      </div>
    </div>
  </div>`;
}
function authPickUser(id){
  AUTH.uid=id;
  AUTH.pin='';
  openAuthScreen();
}
function authKey(k){
  if(k==='clear')AUTH.pin='';
  else if(k==='back')AUTH.pin=AUTH.pin.slice(0,-1);
  else if(AUTH.pin.length<4)AUTH.pin+=k;
  const dots=$$('#pin-dots .pin-dot');
  dots.forEach((d,i)=>d.classList.toggle('on',i<AUTH.pin.length));
  if(AUTH.pin.length===4){
    const sel=S.employees.find(e=>e.id===AUTH.uid);
    const match=(sel&&sel.pin===AUTH.pin)?sel:S.employees.find(e=>e.pin===AUTH.pin);
    if(match){
      setTimeout(()=>completeSignIn(match,'POS PIN Pad'),140);
    }else{
      dots.forEach(d=>{d.classList.remove('on');d.classList.add('err')});
      S.logins.unshift({who:sel?sel.name:'Unknown',role:sel?sel.role:'—',ip:'81.2.64.19',dev:'POS Terminal · REG-01',time:new Date(),ok:false});
      saveState();
      toast('Invalid 4-digit PIN','err');
      setTimeout(()=>{AUTH.pin='';dots.forEach(d=>d.classList.remove('err'))},520);
    }
  }
}
function submitEmailAuth(){
  const em=($('#au-email')?.value||'').trim().toLowerCase();
  const pw=($('#au-pass')?.value||'').trim();
  const u=S.employees.find(e=>e.email.toLowerCase()===em);
  if(!u||(u.password||'admin123')!==pw){
    S.logins.unshift({who:u?u.name:em||'Unknown',role:u?u.role:'—',ip:'81.2.64.19',dev:'Web Back-Office',time:new Date(),ok:false});
    saveState();
    return toast('Invalid email or password (try admin123)','err');
  }
  completeSignIn(u,'Web Back-Office');
}
function completeSignIn(emp,dev='POS Terminal'){
  S.user={id:emp.id,name:emp.name,role:emp.role,branch:emp.branch,email:emp.email,pin:emp.pin};
  const real=S.employees.find(e=>e.id===emp.id);
  if(real){real.onShift=true;real.last=new Date()}
  try{localStorage.setItem('monarch_pos_user_v1',JSON.stringify(S.user))}catch(e){}
  S.logins.unshift({who:emp.name,role:emp.role,ip:'81.2.64.19',dev,time:new Date(),ok:true});
  audit('login',`Signed in via ${dev}`,emp.role);
  updateUserChip();
  const ov=$('#auth-ov');
  if(ov){ov.classList.add('out');setTimeout(()=>$('#auth-root').innerHTML='',320)}
  toast(`Welcome back, <b>${esc(emp.name)}</b> (${emp.role})`);
  refresh();
}
function lockPOS(){
  $('#pop-root').innerHTML='';
  if(S.user)AUTH.uid=S.user.id;
  audit('login','Terminal locked',S.user?S.user.name:'');
  openAuthScreen(true);
}
function signOutUser(){
  $('#pop-root').innerHTML='';
  const prev=S.user?S.user.name:'User';
  audit('login','Signed out',prev);
  S.user=null;
  try{localStorage.removeItem('monarch_pos_user_v1')}catch(e){}
  openAuthScreen(false);
}
function openUserMenu(e){
  e.stopPropagation();
  if($('#pop-root .pop')){$('#pop-root').innerHTML='';return}
  const u=S.user||S.employees[0];
  const emp=S.employees.find(x=>x.id===u.id)||u;
  const r=$('#me-btn').getBoundingClientRect();
  const perms=(S.matrix[u.role]||'').split(' ').filter(Boolean);
  $('#pop-root').innerHTML=`<div class="pop" style="top:${r.bottom+10}px;right:${Math.max(12,innerWidth-r.right)};width:310px">
    <div style="padding:16px 18px;border-bottom:1px solid var(--border);display:flex;gap:12px;align-items:center">
      ${avatar(u.name,42)}
      <div style="min-width:0;flex:1">
        <b style="display:block;font-size:14px">${esc(u.name)}</b>
        <div class="xs muted">${esc(u.email)}</div>
        <div class="row" style="gap:6px;margin-top:5px">
          <span class="badge pri">${u.role}</span>
          <span class="badge ${emp.onShift?'ok':'warn'} dot">${emp.onShift?'On shift':'Off shift'}</span>
        </div>
      </div>
    </div>
    <div style="padding:10px 14px;border-bottom:1px solid var(--border);background:var(--surface-2)">
      <div class="xs muted" style="margin-bottom:6px">ACTIVE PERMISSIONS (${perms.length}/${S.perms.length})</div>
      <div class="row wrap" style="gap:4px">${perms.slice(0,6).map(k=>`<span class="badge" style="font-size:10px;height:20px">${(S.perms.find(p=>p[0]===k)||[0,k])[1]}</span>`).join('')}${perms.length>6?`<span class="badge" style="font-size:10px;height:20px">+${perms.length-6} more</span>`:''}</div>
    </div>
    <div style="padding:6px">
      <button class="cmd-r" onclick="const emp=S.employees.find(x=>x.id===${u.id});if(emp){emp.onShift=!emp.onShift;audit('user',(emp.onShift?'Clocked in':'Clocked out')+' · '+emp.name);toast(emp.name+' '+(emp.onShift?'clocked in':'clocked out'))}$('#pop-root').innerHTML='';refresh()">
        <span class="ri">${ic('clock',15)}</span>${emp.onShift?'Clock out of shift':'Clock in to shift'}<small>Shift</small>
      </button>
      <button class="cmd-r" onclick="lockPOS()">
        <span class="ri">${ic('lock',15)}</span>Switch user / PIN lock<small>Ctrl+L</small>
      </button>
      <button class="cmd-r" onclick="$('#pop-root').innerHTML='';go('employees')">
        <span class="ri">${ic('userCheck',15)}</span>Team & permissions<small>Manage</small>
      </button>
      <button class="cmd-r" style="color:var(--danger)" onclick="signOutUser()">
        <span class="ri" style="color:var(--danger)">${ic('logout',15)}</span>Sign out<small>Exit</small>
      </button>
    </div>
  </div>`;
}

/* ================= INIT ================= */
const _render=render;render=function(id,k){_render(id,k);if(id==='ai')setTimeout(typeBrief,500)};

(function init(){
  try{
    if(localStorage.getItem('mon-theme')==='dark')document.documentElement.dataset.theme='dark';
    if(localStorage.getItem('mon-col')==='1')document.body.classList.add('collapsed');
  }catch(e){}
  $$('[data-ic]').forEach(el=>el.innerHTML=ic(el.dataset.ic,+el.dataset.s||18));
  $('#theme-btn').innerHTML=ic(document.documentElement.dataset.theme==='dark'?'sun':'moon',18);
  $('#branch-sel').innerHTML=Object.keys(BF).map(b=>`<option>${b}</option>`).join('');
  updateBell();
  updateUserChip();
  let first='';
  try{first=location.hash.slice(1)}catch(e){}
  render(PAGES[first]?first:'overview');
  if(!S.user)openAuthScreen(false);
  setTimeout(()=>{$('#splash').classList.add('out');countUps($('#view'))},1150);
  setTimeout(()=>$('#splash')?.remove(),1900);
})();
